package main
import("encoding/json";"os";"path/filepath";"testing")
func TestFarmIsolation(t *testing.T){r:=t.TempDir();idx,e:=loadIndex(r);if e!=nil{t.Fatal(e)};original,_:=slotDir(r,"original");os.MkdirAll(original,0700);os.WriteFile(filepath.Join(original,"save.marker"),[]byte("legacy"),0600);idx,e=switchFarm(r,idx,SwitchRequest{Op:"new",From:idx.Active});if e!=nil{t.Fatal(e)};if idx.Active!="farm-2"{t.Fatal(idx)};newer,_:=slotDir(r,idx.Active);if _,e=os.Stat(filepath.Join(newer,"save.marker"));!os.IsNotExist(e){t.Fatal("new farm copied old progress")};os.WriteFile(filepath.Join(newer,"save.marker"),[]byte("new"),0600);idx,e=switchFarm(r,idx,SwitchRequest{Op:"load",Slot:"original",From:idx.Active});if e!=nil{t.Fatal(e)};b,_:=os.ReadFile(filepath.Join(original,"save.marker"));if string(b)!="legacy"{t.Fatal("original save altered")};idx,e=loadIndex(r);if e!=nil||idx.Active!="original"||len(idx.Slots)!=2{t.Fatal(idx,e)};for _,req:=range []SwitchRequest{{Op:"load",Slot:"../oops",From:idx.Active},{Op:"new",From:"wrong"},{Op:"delete",From:idx.Active},{Op:"load",Slot:"farm-777",From:idx.Active}}{if _,e=switchFarm(r,idx,req);e==nil{t.Fatal("accepted",req)}}}
func TestSaveCatalogDamageDoesNotReset(t *testing.T){r:=t.TempDir();os.WriteFile(filepath.Join(r,"save-index.json"),[]byte("corrupt"),0600);if _,e:=loadIndex(r);e==nil{t.Fatal("silently reset catalog")}}
func TestSaveRequestRoundtrip(t *testing.T){r:=t.TempDir();idx,_:=loadIndex(r);b,_:=json.Marshal(SwitchRequest{Op:"new",From:idx.Active});os.WriteFile(filepath.Join(r,"save-switch.json"),b,0600);idx,e:=consumeSwitch(r,idx);if e!=nil||idx.Active!="farm-2"{t.Fatal(idx,e)};if _,e=os.Stat(filepath.Join(r,"save-switch.json"));!os.IsNotExist(e){t.Fatal("stale request")}}
func TestFarmIdValidation(t *testing.T){for _,s:=range []string{"../","farm-01","farm--2","C:\\x","farm-2/../","farm-2\\x","farm-1000001"}{if validSlot(s){t.Fatal(s)}};for _,s:=range []string{"original","farm-2","farm-100"}{if !validSlot(s){t.Fatal(s)}}}
func TestUnindexedFarmIsNotOverwritten(t *testing.T){r:=t.TempDir();idx,_:=loadIndex(r);p,_:=slotDir(r,"farm-2");os.MkdirAll(p,0700);os.WriteFile(filepath.Join(p,"recovery"),[]byte("keep"),0600);idx,e:=switchFarm(r,idx,SwitchRequest{Op:"new",From:idx.Active});if e!=nil||idx.Active!="farm-3"{t.Fatal(idx,e)}}
